    P = list(map(int, input_data[1:N + 1]))

    bit = [0] * (N + 1)
    for i in range(1, N + 1):
        bit[i] += 1
        j = i + (i & -i)
        if j <= N:
            bit[j] += bit[i]

    steps = [1 << j for j in range(N.bit_length() - 1, -1, -1)]
    ans = [0] * N

    for i in range(N - 1, -1, -1):
        k = P[i]
        idx = 0

        for step in steps:
            nxt = idx + step
            if nxt <= N and bit[nxt] < k:
                idx = nxt
                k -= bit[nxt]

        pos = idx + 1
        ans[pos - 1] = i + 1

        while pos <= N:
            bit[pos] -= 1
            pos += pos & -pos

    print(*ans)

if __name__ == "__main__":
